/**
 * Recover token usage for cloud turns that finished without it on
 * `turn.completed`.
 *
 * Cloud `run.wait()` often drops streamed usage after SSE reconnect. The
 * playground Trace tab only renders what is on the event, so those turns
 * stay blank unless usage is backfilled from `Agent.getUsage` when the
 * stream is read.
 */
export function usageTokenSum(usage) {
    if (usage === undefined) {
        return 0;
    }
    return usage.inputTokens + usage.outputTokens + usage.cacheReadTokens + usage.cacheWriteTokens;
}
export function isUsageMissingCompletedTurn(event) {
    return event.type === "turn.completed" && usageTokenSum(event.data.usage) <= 0;
}
export function cloudSdkAgentIdFromEvents(events) {
    let sdkAgentId;
    for (const event of events) {
        if (event.type !== "agent.bound") {
            continue;
        }
        const id = event.data.sdkAgentId.trim();
        if (id.startsWith("bc-")) {
            sdkAgentId = id;
        }
    }
    return sdkAgentId;
}
/**
 * Copy usage onto `turn.completed` events that have none. Returns undefined
 * when the snapshot cannot be attributed safely (multiple unmatched turns).
 */
export function applyCloudUsageToEvents(events, billed) {
    const completedIndexes = [];
    const missingIndexes = [];
    for (let i = 0; i < events.length; i++) {
        const event = events[i];
        if (event === undefined || event.type !== "turn.completed") {
            continue;
        }
        completedIndexes.push(i);
        if (isUsageMissingCompletedTurn(event)) {
            missingIndexes.push(i);
        }
    }
    if (missingIndexes.length === 0) {
        return [...events];
    }
    const patches = new Map();
    if (missingIndexes.length === 1 &&
        completedIndexes.length === 1 &&
        usageTokenSum(billed.usage) > 0) {
        const index = missingIndexes[0];
        if (index !== undefined) {
            patches.set(index, billed.usage);
        }
    }
    else if (billed.runs.length === missingIndexes.length &&
        billed.runs.every((run) => usageTokenSum(run.usage) > 0)) {
        for (let i = 0; i < missingIndexes.length; i++) {
            const index = missingIndexes[i];
            const run = billed.runs[i];
            if (index === undefined || run === undefined) {
                return undefined;
            }
            patches.set(index, run.usage);
        }
    }
    else {
        return undefined;
    }
    return events.map((event, index) => {
        const usage = patches.get(index);
        if (usage === undefined || event.type !== "turn.completed") {
            return event;
        }
        return { ...event, data: { ...event.data, usage } };
    });
}
export function mapSdkTokenUsage(usage) {
    const mapped = {
        inputTokens: usage.inputTokens,
        outputTokens: usage.outputTokens,
        cacheReadTokens: usage.cacheReadTokens,
        cacheWriteTokens: usage.cacheWriteTokens,
    };
    if (usage.reasoningTokens !== undefined) {
        mapped.reasoningTokens = usage.reasoningTokens;
    }
    return mapped;
}
